select job_name, to_char(run_time,'MM-DD HH24:MI') t, status, rows_affected, left(details->>'response',600) r from cron_job_audit where ((run_time >= '2026-11-13 12:39' and run_time < '2026-11-13 12:42') or (run_time >= '2026-11-14 12:39' and run_time < '2026-11-14 12:42') or (run_time >= '2026-11-15 12:39' and run_time < '2026-11-15 12:42') or (run_time >= '2026-11-12 12:39' and run_time < '2026-11-12 12:42')) and job_name ~ 'served-forecast'
